--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,6,1,3,'MacBook Air M5 13 inch 10CPU 8GPU 16GB/512GB','macbook-air-m5-13-inch-10cpu-8gpu-16gb512gb','HH-8172','Chính hãng Apple Việt Nam. Thiết kế sang trọng, hiệu năng vượt trội, bảo hành chính hãng 12-24 tháng.','<h3>Đặc điểm nổi bật của MacBook Air M5 13 inch 10CPU 8GPU 16GB/512GB</h3><p>MacBook Air M5 13 inch 10CPU 8GPU 16GB/512GB là dòng sản phẩm cao cấp phân phối chính hãng bởi Apple. Sản phẩm sở hữu thiết kế tinh xảo, thời lượng pin ấn tượng, màn hình sắc nét chuẩn điện ảnh cùng hiệu năng xử lý tác vụ công việc và giải trí đỉnh cao.</p><h4>Cấu hình tối ưu</h4><ul><li>Hiệu năng mượt mà, phản hồi tức thì với các ứng dụng nặng.</li><li>Hệ thống tản nhiệt tiên tiến giữ máy luôn mát mẻ.</li><li>Bàn phím gõ êm ái, hành trình phím sâu, đèn nền tiện lợi.</li><li>Bảo hành chính hãng 12-24 tháng, 1 đổi 1 trong 30 ngày nếu có lỗi từ NSX.</li></ul>',12,'active',2302,'2026-08-24 03:01:08','2026-08-24 03:01:08',NULL),(2,6,1,2,'MacBook Air M5 13 inch 10CPU 10GPU 16GB/1TB','macbook-air-m5-13-inch-10cpu-10gpu-16gb1tb','HH-8173','Chính hãng Apple Việt Nam. Thiết kế sang trọng, hiệu năng vượt trội, bảo hành chính hãng 12-24 tháng.','<h3>Đặc điểm nổi bật của MacBook Air M5 13 inch 10CPU 10GPU 16GB/1TB</h3><p>MacBook Air M5 13 inch 10CPU 10GPU 16GB/1TB là dòng sản phẩm cao cấp phân phối chính hãng bởi Apple. Sản phẩm sở hữu thiết kế tinh xảo, thời lượng pin ấn tượng, màn hình sắc nét chuẩn điện ảnh cùng hiệu năng xử lý tác vụ công việc và giải trí đỉnh cao.</p><h4>Cấu hình tối ưu</h4><ul><li>Hiệu năng mượt mà, phản hồi tức thì với các ứng dụng nặng.</li><li>Hệ thống tản nhiệt tiên tiến giữ máy luôn mát mẻ.</li><li>Bàn phím gõ êm ái, hành trình phím sâu, đèn nền tiện lợi.</li><li>Bảo hành chính hãng 12-24 tháng, 1 đổi 1 trong 30 ngày nếu có lỗi từ NSX.</li></ul>',12,'active',804,'2026-08-24 03:01:08','2026-08-24 03:01:08',NULL),(3,6,1,1,'MacBook Air M5 15 inch 10CPU 10GPU 16GB/512GB','macbook-air-m5-15-inch-10cpu-10gpu-16gb512gb','HH-8175','Chính hã